import fs from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { checkEnvironment } from "./head/scripts/gate-cache.ts";
import { isolatedEnvironment } from "./head/scripts/local-gate.ts";
const root=path.join(import.meta.dir,`benchmark-state-${process.pid}`);
Object.assign(process.env,isolatedEnvironment(root,checkEnvironment(process.env)),{TMPDIR:root});
const head=path.join(import.meta.dir,"head");
const beforePrincipal=path.join(head,"src/lib/team/workspacePrincipal.before.ts");
const beforeFence=path.join(head,"src/lib/mcp/workspaceFence.before.ts");
fs.writeFileSync(beforePrincipal,spawnSync("git",["show","d223f3aa851bb47dc00568742d46baebf10d17bd:src/lib/team/workspacePrincipal.ts"],{cwd:head,encoding:"utf8"}).stdout);
fs.writeFileSync(beforeFence,fs.readFileSync(path.join(head,"src/lib/mcp/workspaceFence.ts"),"utf8").replace('"@/lib/team/workspacePrincipal"','"@/lib/team/workspacePrincipal.before"'));
const {teamStore,resetTeamStoreForTests}=await import("./head/src/lib/team/store.ts");
const {createWorkspace}=await import("./head/src/lib/team/workspaces.ts");
const {statePath}=await import("./head/src/lib/configDir.ts");
const {emptyLaunchProfile}=await import("./head/src/lib/accounts/migration/contracts.ts");
const before=(await import(beforeFence)).withWorkspaceMcpFence;
const after=(await import("./head/src/lib/mcp/workspaceFence.ts")).withWorkspaceMcpFence;
const store=teamStore();
const at="2026-10-20T09:00:00.000Z";
const owner={id:"m_owner",name:"Owner",role:"owner" as const,status:"active" as const,color:"teal" as const,telegram:null,createdAt:at,createdBy:"claim",revokedAt:null};
store.insertMember(owner);createWorkspace(store,owner,{id:`w_${"a".repeat(32)}`,name:"Alpha",projects:["project-alpha"]});
const seats:Record<string,unknown>={};
for(let i=0;i<500;i++) {
 const project=`project-seat-${String(i).padStart(4,"0")}`;
 seats[project]={project,seatEpoch:i+1,conversationId:`conversation_seat_${i}`,path:`seat-${i}.jsonl`,engine:null,model:null,runtimeIdentityFrozen:false,mandate:"x".repeat(3500),promptVersion:null,predecessorConversationId:null,triggeredBy:null,state:"active",intent:{clientRequestId:`seed-${i}`,mode:"existing",launchId:null,error:null},designatedAt:at,activatedAt:at};
}
const payload=JSON.stringify({schemaVersion:1,nextSeatEpoch:501,seats,seatLineage:[],pending:{},revocations:[],history:[],rollbacks:{}});
const file=statePath("orchestrator-seats.json");fs.writeFileSync(file,payload);
console.log(JSON.stringify({startedAt:new Date().toISOString(),runtime:process.version,bun:Bun.version,seats:500,bytes:Buffer.byteLength(payload),samples:20,warmup:3,unit:"ms",registry:"in-memory chain",aggregate:"median"}));
const result=[];
for(const depth of [1,4,10]) {
 const conversations=Object.fromEntries(Array.from({length:depth},(_,i)=>[`conversation_${i}`,{id:`conversation_${i}`,generations:[{launchProfile:emptyLaunchProfile({cwd:root,project:"project-alpha",...(i+1<depth?{parentConversationId:`conversation_${i+1}`}:{})})}]}]));
 const deps={attentionAuthority:()=>({kind:"worker",conversationId:"conversation_0",role:"builder"}),workspaceConversation:(id:string)=>conversations[id]??null};
 const target={callTool:async()=>({ok:true,toolName:"list_tasks",clientRequestId:null,replayed:false})};
 const row:Record<string,number>={depth};
 for(const [name,wrap] of [["before",before],["after",after]] as const) {
  const service=wrap(target,deps);const times=[];let warmReads=0,measuredReads=0;let measured=false;
  const original=fs.readFileSync;
  fs.readFileSync=((name:any,...args:any[])=>{if(name===file){if(measured)measuredReads++;else warmReads++;}return (original as any)(name,...args);}) as typeof fs.readFileSync;
  for(let i=0;i<23;i++){measured=i>=3;const start=performance.now();await service.callTool("list_tasks",{});if(i>=3)times.push(performance.now()-start);}
  times.sort((a,b)=>a-b);row[name]=(times[9]+times[10])/2;fs.readFileSync=original;row[`${name}WarmReads`]=warmReads;row[`${name}MeasuredReads`]=measuredReads;
 }
 result.push(row);console.log(JSON.stringify(row));
}
// A solo caller uses the same ten-generation chain and nonempty seats file.
resetTeamStoreForTests();fs.renameSync(statePath("team/team.sqlite"),statePath("saved-team.sqlite"));
let reads=0;const realRead=fs.readFileSync;fs.readFileSync=((name:any,...args:any[])=>{if(name===file)reads++;return (realRead as any)(name,...args);}) as typeof fs.readFileSync;
const lookup=(id:string)=>{const index=Number(id.slice("conversation_".length));return {id,generations:[{launchProfile:emptyLaunchProfile({cwd:root,project:"project-alpha",...(index<9?{parentConversationId:`conversation_${index+1}`}:{})})}]};};
await after({callTool:async()=>({ok:true})},{attentionAuthority:()=>({kind:"worker",conversationId:"conversation_0",role:"builder"}),workspaceConversation:lookup}).callTool("list_tasks",{});
fs.readFileSync=realRead;console.log(JSON.stringify({soloSeatsReads:reads}));
fs.unlinkSync(beforePrincipal);fs.unlinkSync(beforeFence);

