import fs from "node:fs";
import path from "node:path";
import { checkEnvironment } from "./head/scripts/gate-cache.ts";
import { isolatedEnvironment } from "./head/scripts/local-gate.ts";
const root=import.meta.dir;
const runner=process.env.OWNED_GATE_RUNNER; if(!runner) throw Error("select the recorded installed owned runner");
const phases=[{label:"final-remainder",side:"head",files:JSON.parse(fs.readFileSync(path.join(root,"green-selection.json"),"utf8"))}];
for(const phase of phases){
 const report=path.join(root,`resume-${phase.label}.json`);
 const outcomes:any[]=fs.existsSync(report)?JSON.parse(fs.readFileSync(report,"utf8")):[];
 const done=new Set(outcomes.map(row=>row.file));
 for(const file of phase.files){
  if(done.has(file))continue;
  const sandbox=fs.mkdtempSync(path.join(root,`recheck-${phase.side}-`));
  const env=isolatedEnvironment(sandbox,checkEnvironment(process.env));
  env.LLV_GATE_LOCK_DIR=path.join(sandbox,"cpu-gate");fs.mkdirSync(env.LLV_GATE_LOCK_DIR,{recursive:true});
  env.LLV_OWNED_RUN_TIMEOUT_MS="300000";
  const junit=path.join(sandbox,"report.xml"),log=path.join(sandbox,"output.log");
  const fd=fs.openSync(log,"w");
  const startedAt=new Date().toISOString(),began=performance.now();
  console.log(`START ${phase.label} ${file}`);
  let child;
  try { child=Bun.spawn([process.execPath,runner,"--budget","310000",process.execPath,runner,"setsid","--wait",process.execPath,"run","test",file,"--reporter=junit",`--reporter-outfile=${junit}`],{cwd:path.join(root,phase.side),env,stdio:["ignore",fd,fd]});await child.exited; }
  finally {fs.closeSync(fd);}
  const output=fs.readFileSync(log,"utf8");
  const row={file,side:phase.side,status:child.exitCode,signal:child.signalCode,startedAt,elapsedMs:performance.now()-began,summaryComplete:/Ran \d+ tests? across 1 file/.test(output),junit:fs.existsSync(junit)?fs.readFileSync(junit,"utf8"):null,stderr:output};
  outcomes.push(row);fs.writeFileSync(report,JSON.stringify(outcomes,null,2));
  console.log(`COMPLETE ${phase.label} ${file} exit=${row.status} summary=${row.summaryComplete}`);
 }
 console.log(`RAN ${phase.label} ${outcomes.length}/${phase.files.length}`);
}
console.log("RESUME-COMPLETE");

