const {parseReport,appendOwnershipFailure,compareTests}=await import("./head/scripts/local-gate-tests.ts");
const load=(name:string)=>JSON.parse(fs.readFileSync(path.join(root,name),"utf8"));
const sources=[{name:"head",file:"resume-final-remainder.json",side:"head"},{name:"base1",file:"resume-base-one.json",side:"base"},{name:"base2",file:"resume-base-two.json",side:"base"}];
for(const [name,file,side] of [
 ["extraBase1","resume-confirm-base-one.json","base"],["extraBase2","resume-confirm-base-two.json","base"],
 ["confirmHead1","resume-confirm-head-one.json","head"],["confirmHead2","resume-confirm-head-two.json","head"],["confirmHead3","resume-confirm-head-three.json","head"],
])if(fs.existsSync(path.join(root,file!)))sources.push({name:name!,file:file!,side:side!});
const output:any={};
for(const source of sources){
 output[source.name]=load(source.file).map((row:any)=>{
  const text=row.stderr??"";
  let parsed:any=null,error:string|null=null;
  try{
   if(!row.summaryComplete||!row.junit||![0,1].includes(row.status))throw Error(text.includes("owned runner: deadline expired")?"execution deadline":"incomplete runner");
   parsed=parseReport(row.junit,text,row.file,path.join(root,source.side));
   const owned=text.split("\n").find((line:string)=>line.startsWith("owned runner: surviving owned processes:"));
   if(owned&&row.status!==0)appendOwnershipFailure(parsed.failures,row.file,owned);
   if((row.status===0)!==(parsed.failures.length===0))throw Error("runner exit disagrees with report");
  }catch(cause){error=String(cause);}
  const diagnostic=text.match(/# Unhandled error between tests\s*\n-+\n([\s\S]*?)\n-+/)?.[1]?.split(path.join(root,source.side)+path.sep).join("<checkout>/") ?? null;
  return {runnerDiagnostic:diagnostic,file:row.file,status:row.status,startedAt:row.startedAt??null,elapsedMs:row.elapsedMs??null,summaryComplete:row.summaryComplete,parsed,error,counts:Object.fromEntries(["pass","fail","skip","error","errors"].flatMap(name=>{const m=[...text.matchAll(new RegExp(`^\\s*(\\d+) ${name}\\s*$`,"gm"))].at(-1);return m?[[name,Number(m[1])]]:[];}))};
 });
}
output.base1.push(...(output.extraBase1??[]));output.base2.push(...(output.extraBase2??[]));
output.confirmations={};
for(const name of ["confirmHead1","confirmHead2","confirmHead3"])for(const row of output[name]??[])(output.confirmations[row.file]??=[]).push(row);
const b1=new Map(output.base1.map((r:any)=>[r.file,r])),b2=new Map(output.base2.map((r:any)=>[r.file,r]));
output.comparisons=output.head.filter((r:any)=>r.status!==0).map((head:any)=>{
 const left:any=b1.get(head.file),right:any=b2.get(head.file);
 const one=head.parsed&&left?.parsed?compareTests({...left.parsed,completed:[head.file],elapsedMs:0},{...head.parsed,completed:[head.file],elapsedMs:0}):null;
 const two=head.parsed&&right?.parsed?compareTests({...right.parsed,completed:[head.file],elapsedMs:0},{...head.parsed,completed:[head.file],elapsedMs:0}):null;
 return {file:head.file,base1Introduced:one?.introduced??null,base2Introduced:two?.introduced??null,pairedIncomplete:!head.parsed&&!left?.parsed&&!right?.parsed&&left?.status===head.status&&right?.status===head.status};
});
for (const row of [...output.head, ...Object.values(output.confirmations).flat()]) {
 const left:any=b1.get(row.file),right:any=b2.get(row.file);
 if(row.parsed && left?.parsed && right?.parsed) row.comparison={
  one:compareTests({...left.parsed,completed:[row.file],elapsedMs:0},{...row.parsed,completed:[row.file],elapsedMs:0}),
  two:compareTests({...right.parsed,completed:[row.file],elapsedMs:0},{...row.parsed,completed:[row.file],elapsedMs:0}),
 };
}
fs.writeFileSync(path.join(root,"canonical-results.json"),JSON.stringify(output,null,2));
console.log(JSON.stringify({head:output.head.length,base1:output.base1.length,base2:output.base2.length,red:output.comparisons.length}));
for(const row of output.comparisons)if(row.base1Introduced?.length||row.base2Introduced?.length||row.base1Introduced===null&&!row.pairedIncomplete)console.log(JSON.stringify(row));
